INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('bdf2403a-b3fa-51a8-ae55-5e979c799021'::uuid,'MM.1.1','201403d9-9da2-5397-abd3-ed2cd49edec5'::uuid,'The hospital has a multidisciplinary policy and procedure on patient specific information to be readily accessible to all healthcare professionals. The information includes, but is not limited to, the following: MM.1.1.1 Patient’s age and sex. MM.1.1.2 Current medications. MM.1.1.3 Diagnoses, co-morbidities. MM.1.1.4 Laboratory values. MM.1.1.5 Allergies. MM.1.1.6 Body weight and height. MM.1.1.7 Pregnancy and lactation status.','["D"]'::jsonb,FALSE,1,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
