INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('d7e19f7b-b08f-51d7-935a-0125d07b7dc1'::uuid,'MM.2.1','5b293de5-06fd-5dad-b672-99d2794a2074'::uuid,'The pharmaceutical care department has a clear organizational structure.','["D"]'::jsonb,FALSE,1,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
