INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('67cc8709-960d-5bf0-b0c4-0e881f2a7833'::uuid,'MM.4.2','d95eb4cf-2870-5b48-87e5-0b4b4511eb95'::uuid,'Policies and procedures are developed in collaboration with relevant staff, such as medical, nursing, and management staff.','["D"]'::jsonb,FALSE,2,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('2b131e72-8803-59be-a127-ba09305cd487'::uuid,'MM.4.3','d95eb4cf-2870-5b48-87e5-0b4b4511eb95'::uuid,'Updated policies and procedures manual is readily accessible to all healthcare professionals involved in medication use.','["I"]'::jsonb,FALSE,2,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('35c39776-6c0c-53ef-b0f7-8ab3d289eadb'::uuid,'MM.4.4','d95eb4cf-2870-5b48-87e5-0b4b4511eb95'::uuid,'Appropriate sources of drug information are readily available to all healthcare professionals involved in medication use. (e.g., books, manuals, CDs/DVDs, online subscription to drug information resources).','["I"]'::jsonb,FALSE,3,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('c582e122-614d-538d-b0c3-5d367e530ac9'::uuid,'MM.4.5','d95eb4cf-2870-5b48-87e5-0b4b4511eb95'::uuid,'The pharmaceutical care services are provided twenty four hours a day, seven days a week for inpatients and emergency patients','["I", "D"]'::jsonb,FALSE,3,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('d862ce9a-a739-5aa4-b664-d187516c07fd'::uuid,'MM.4.6','d95eb4cf-2870-5b48-87e5-0b4b4511eb95'::uuid,'There is a pharmacist on-call whenever the inpatient pharmacy is closed.','["I", "D"]'::jsonb,FALSE,3,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('2baa98be-7974-5267-9d04-573a68c7fc39'::uuid,'MM.5.1','7d095941-dae6-536e-8fcd-d99f1b0b52c4'::uuid,'There is a written multidisciplinary plan for managing high-alert medications and hazardous pharmaceutical chemicals. It includes identification, location, labeling, storage, dispensing, and administration of high-alert medications.','["D"]'::jsonb,TRUE,3,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('736cfc5c-e3cd-505a-8941-cdb21d686f44'::uuid,'MM.5.2','7d095941-dae6-536e-8fcd-d99f1b0b52c4'::uuid,'The hospital identifies an annually updated list of high-alert medications and hazardous pharmaceutical chemicals based on its own data and national and international recognized organizations (e.g., Institute of Safe Medication Practice, World Health Organization). The list contains, but is not limited to, the following: MM.5.2.1 Controlled and narcotics medications. MM.5.2.2 Neuromuscular blockers. MM.5.2.3 Chemotherapeutic agents. MM.5.2.4 Concentrated electrolytes (e.g., hypertonic sodium chloride, concentrated potassium salts). MM.5.2.5 Antithrombotic medications (e.g., heparin, warfarin). MM.5.2.6 Insulins. MM.5.2.7 Anesthetic medications (e.g., propofol, ketamine). MM.5.2.8 Investigational (research) drugs, as applicable. MM.5.2.9 Other medications as identified by the hospital.','["D"]'::jsonb,TRUE,3,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
