INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('86f30a2c-e49d-589a-9bf1-4e882641d99e'::uuid,'MM.5.3','7d095941-dae6-536e-8fcd-d99f1b0b52c4'::uuid,'The hospital plan for managing high-alert medications and hazardous pharmaceutical chemicals is implemented. This includes, but is not limited to, the following: MM.5.3.1 Improving access to information about high-alert medications. MM.5.3.2 Limiting access to high-alert medications. MM.5.3.3 Using auxiliary labels or computerized alerts if available. MM.5.3.4 Standardizing the ordering, transcribing, preparation, dispensing, administration, and monitoring of high-alert medications. MM.5.3.5 Employing independent double checks.','["O", "I"]'::jsonb,TRUE,4,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
