INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('2da9d8b6-d23f-5b89-a1ec-43c5a459714d'::uuid,'MM.5.4','7d095941-dae6-536e-8fcd-d99f1b0b52c4'::uuid,'The hospital develops and implements standard concentrations for all medications administered by intravenous infusion.','["I", "D"]'::jsonb,TRUE,4,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('6f7ed2ab-af8e-516a-8a88-a1e711f936fa'::uuid,'MM.6.1','000194de-9e31-5a23-9a07-8e1afe9bd145'::uuid,'There is a multidisciplinary policy and procedure on handling look-alike/sound-alike (LASA) medications.','["D"]'::jsonb,TRUE,4,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('1688d5ae-5f7a-59a9-8886-1f8f831b82d0'::uuid,'MM.6.2','000194de-9e31-5a23-9a07-8e1afe9bd145'::uuid,'The hospital reviews and revises annually its list of confusing drug names, which include LASA medication name pairs that the hospital stores, dispenses, and administers','["D"]'::jsonb,TRUE,4,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('f44b8cb6-f685-5d39-a9c3-c39cea57f84f'::uuid,'MM.6.3','000194de-9e31-5a23-9a07-8e1afe9bd145'::uuid,'The hospital takes actions to prevent errors involving LASA medications including the following, as applicable: MM.6.3.1 Providing education on LASA medications to healthcare professionals at orientation and as part of continuing education. MM.6.3.2 Using both the brand and generic names for prescribing LASA medications. MM.6.3.3 Writing the diagnosis/ indication of the LASA medication on the prescription. MM.6.3.4 Changing the appearance of look-alike product package.. MM.6.3.5 Reading carefully the label each time a medication is accessed, and/or prior to administration MM.6.3.6 Minimizing the use of verbal and telephone orders. MM.6.3.7 Checking the purpose/indication of the medication on the prescription prior to dispensing and administering. MM.6.3.8 Placing LASA medications in locations separate from each other or in non- alphabetical order.','["D", "I", "O"]'::jsonb,TRUE,4,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
