INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('deebce3b-ee63-5bfd-80cb-438df2dceb7c'::uuid,'MM.7.1','17e2e7be-d591-57a1-8ef5-00f1605c5851'::uuid,'There is a pharmacy and therapeutics committee chaired by a senior medical or pharmaceutical care staff member.','["PH"]'::jsonb,FALSE,5,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('5fd7ef9f-ab16-5c28-88d5-0d2ab9719af6'::uuid,'MM.7.2','17e2e7be-d591-57a1-8ef5-00f1605c5851'::uuid,'There are terms of reference for the pharmacy and therapeutics committee that include committee’s functions, membership, quorum, frequency of meetings, approval, and distribution of minutes.','["PH"]'::jsonb,FALSE,5,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('b84261e6-27df-55c9-8295-88ad24c48f57'::uuid,'MM.7.3','17e2e7be-d591-57a1-8ef5-00f1605c5851'::uuid,'The pharmacy and therapeutics committee meets on a regular basis (at least quarterly).','["PH"]'::jsonb,FALSE,5,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('869b6fbb-7d45-5dc0-a953-b0babd06c9b9'::uuid,'MM.7.4','17e2e7be-d591-57a1-8ef5-00f1605c5851'::uuid,'The meeting minutes of the committee reflects the members in attendance, items discussed, decisions reached, lead accountability assigned for action undertaken and subsequent reporting, as well as follow-up data for these activities.','["PH"]'::jsonb,FALSE,5,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('bf745921-e7ab-563d-add6-715681b80ea9'::uuid,'MM.7.5','17e2e7be-d591-57a1-8ef5-00f1605c5851'::uuid,'Functions of the H C pharmacy and therapeutics committee include, but are not limited to, the following: MM.7.5.1 Serve in an evaluative, educational, and advisory capacity to the medical staff and hospital management in all matters pertaining to the use of medications. MM.7.5.2 Develop and approve criteria for selecting medications that include at least indications, effectiveness, risks (potential for medication errors, abuse potential, and sentinel events), or cost. MM.7.5.3 Develop a formulary of drugs accepted for use in the hospital and provide for its constant revision. MM.7.5.4 Establish programs and procedures that help ensure safe and effective drug therapy. MM.7.5.5 Establish programs and procedures that help ensure cost- effective drug therapy. MM.7.5.6 Establish or plan suitable educational programs for the hospital’s professional staff on matters related to drug use. MM.7.5.7 Participate in quality improvement activities related to distribution, administration, and use of medications. MM.7.5.8 Monitor and evaluate adverse drug events and make appropriate recommendations to prevent their recurrence. MM.7.5.9 Establish evidence- based therapeutic guidelines according to the scope of services of the hospital (e.g., intravenous iron, intravenous immunoglobulin, albumin, heparin, chemo protocols, high EOC alert medications, and electrolyte management guidelines). MM.7.5.10 Initiate and/or direct drug use evaluation programs and studies, review the results of such activities, and make appropriate recommendations to optimize drug use. MM.7.5.11 Advise the pharmaceutical care department in the implementation of effective drug distribution and control procedures.. MM.7.5.12 Disseminate information on its actions and approved recommendations to all staff MM.7.5.13 The committee conducts an annual review of its hospital formulary based on safety and efficacy information (e.g., Saudi FDA warnings, international medication safety alerts, hospital-based adverse drug reaction reports, and drug utilization evaluation studies).','["PH"]'::jsonb,FALSE,6,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
