INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('8d20b76f-b163-5262-9806-f9dd44b9c65d'::uuid,'MM.23.3','349f2034-bab1-52a2-a6ee-00b00672171c'::uuid,'Verbal and telephone orders are limited to emergent and urgent situation where immediate written or electronic medication order is not feasible. lear definition of emergent and urgent situations should be included.','["OMR"]'::jsonb,FALSE,17,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
