INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('924a8a84-04df-5a45-bd2a-0778a052ff31'::uuid,'MM.25.4','71f0400b-3f7b-5cb6-9c42-4ee3362b414d'::uuid,'All issues, concerns, or questions regarding medication order or prescription are clarified with the prescriber and documented before medication dispensing.','["I"]'::jsonb,FALSE,19,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('45b62d76-b295-576f-bcbe-94052ef9367a'::uuid,'MM.26.1','3b9a254f-1784-5ff9-882f-5baf02167133'::uuid,'The hospital has a manual for proper aseptic technique and intravenous admixture (e.g., the guidelines of the Saudi Food and Drug Authority, the American Society of HealthSystem Pharmacists, United States Pharmacopoeia USP ).','["D"]'::jsonb,FALSE,19,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('60274588-d734-5a8f-8ab8-ea3a308d8483'::uuid,'MM.26.2','3b9a254f-1784-5ff9-882f-5baf02167133'::uuid,'Sterile compounded preparations are performed by the pharmaceutical care except during emergency or urgency situations in which a delay could harm the patient or when product stability is short.','["D", "I"]'::jsonb,FALSE,19,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('ca6836a6-f3f5-5495-aa60-a29b347bba93'::uuid,'MM.26.3','3b9a254f-1784-5ff9-882f-5baf02167133'::uuid,'Sterile compounded preparations are performed in the clean room by pharmaceutical care staff, qualified in intravenous admixture and aseptic technique.','["PF"]'::jsonb,FALSE,19,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('e5d9639b-068e-5127-9afc-bf6666de6f9a'::uuid,'MM.26.4','3b9a254f-1784-5ff9-882f-5baf02167133'::uuid,'The hospital provides and documents training and competency assessment of nonpharmaceutical care staff involved in compounding sterile preparations outside the pharmaceutical care department during emergency or urgency situations.','["PF"]'::jsonb,FALSE,20,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('b48e9c7e-7856-54a2-b374-02bcbeca967b'::uuid,'MM.26.5','3b9a254f-1784-5ff9-882f-5baf02167133'::uuid,'There is full compliance with aseptic technique in all medication preparation areas all over the hospital.','["O"]'::jsonb,FALSE,20,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('c7279563-705b-58f5-b402-b437495a1e3c'::uuid,'MM.26.6','3b9a254f-1784-5ff9-882f-5baf02167133'::uuid,'Visual inspection is performed for all compounded sterile products by a trained individual for particulate, discoloration, or evidence of loss of integrity.','["O"]'::jsonb,FALSE,20,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('9823fccc-533e-5f9b-bde0-3ecad948cfd1'::uuid,'MM.26.7','3b9a254f-1784-5ff9-882f-5baf02167133'::uuid,'The pharmaceutical care has a clean room that is a functionally separate facility to maintain product sterility.','["O"]'::jsonb,FALSE,20,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('7f856035-868e-5326-a371-f207bbe65f5f'::uuid,'MM.26.8','3b9a254f-1784-5ff9-882f-5baf02167133'::uuid,'The design of the clean room is guided by the professional organizations’ standards (e.g., the American Society of Health- System Pharmacists, United States Pharmacopoeia USP ).','["O"]'::jsonb,FALSE,20,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('aa7fea16-7a78-5820-8d1b-ad8d094c318a'::uuid,'MM.26.9','3b9a254f-1784-5ff9-882f-5baf02167133'::uuid,'The pharmaceutical care uses ISO Class 5 laminar airflow hood for preparing sterile injectable preparations and all other sterile preparations.','["O"]'::jsonb,FALSE,20,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('9bc56b9a-4604-54ab-93a2-8915588e0ea5'::uuid,'MM.26.10','3b9a254f-1784-5ff9-882f-5baf02167133'::uuid,'The laminar airflow hood is tested at least every six months and in accordance with the manufacturer’s requirements, the Saudi Food and Drug Authority guidelines and the professional organizations’ standards ( e.g, American Society of Health-System Pharmacists, United States Pharmacopoeia USP ).','["O"]'::jsonb,FALSE,20,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('36682eda-d621-5d23-8d88-ae8916139a85'::uuid,'MM.26.11','3b9a254f-1784-5ff9-882f-5baf02167133'::uuid,'The hospital implements the written and approved guidelines on intravenous drug stability and compatibility.','["I", "D"]'::jsonb,FALSE,21,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('788a8089-a7f3-5756-b141-8c3b1b12b361'::uuid,'MM.26.12','3b9a254f-1784-5ff9-882f-5baf02167133'::uuid,'Any sterile preparation compounded outside the clean room (e.g., in the patient care area during emergency or urgency situation) is done in an appropriate environment (location, space, cleanliness, traffic, etc.) to prevent contamination.','["O"]'::jsonb,FALSE,21,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
INSERT INTO measurable_elements (id,me_id,standard_id,official_text,eoc,esr,source_page,source_version,active) VALUES ('b2e49a6a-12b7-5125-9f3a-09db962b941e'::uuid,'MM.26.13','3b9a254f-1784-5ff9-882f-5baf02167133'::uuid,'The pharmaceutical care regularly (at least once a month) inspects all areas where sterile preparations are compounded outside the pharmaceutical care clean room.','["D"]'::jsonb,FALSE,21,'CBAHI MM Self-Assessment Tool',TRUE) ON CONFLICT (me_id) DO UPDATE SET standard_id=EXCLUDED.standard_id,official_text=EXCLUDED.official_text,eoc=EXCLUDED.eoc,esr=EXCLUDED.esr,source_page=EXCLUDED.source_page,source_version=EXCLUDED.source_version,active=EXCLUDED.active;
